body:
##### Using Cake 3 alpha 1

When attempting to use a finder query as shown in the code below. I'm getting the following error. It appears that the ORM/Table class is returning a Cake\ORM\Query object where App\Model\Table\Query object is expected.
#### Error

Warning (4096): Argument 1 passed to App\Model\Table\CmsPagesTable::findActive() must be an instance of App\Model\Table\Query, instance of Cake\ORM\Query given, called in /Applications/XAMPP/xamppfiles/htdocs/cake3a/vendor/cakephp/cakephp/src/ORM/Table.php on line 1451 and defined [APP/Model/Table/CmsPagesTable.php, line 65]
#### Used to call Finder Query. Tested in a Cell and a Controller

```
$this->loadModel('CmsPages');
$active = $this->CmsPages->find('active');
$this->set('active_count', $active->count());
```
#### Model Code

```
namespace App\Model\Table;

use Cake\ORM\Table;
use Cake\Validation\Validator;

/**
 * CmsPages Model
 */
class CmsPagesTable extends Table {

/**
 * Initialize method
 *
 * @param array $config The configuration for the Table.
 * @return void
 */
    public function initialize(array $config) {
        $this->table('cms_pages');
        $this->displayField('title');
        $this->primaryKey(['id']);
        $this->addBehavior('Timestamp');

        $this->belongsTo('CmsLanguages', [
            'foreignKey' => 'cms_language_id',
        ]);
        $this->belongsToMany('CmsCategories', [
            'foreignKey' => 'cms_page_id',
            'targetForeignKey' => 'cms_category_id',
            'joinTable' => 'cms_pages_cms_categories',
        ]);
    }

/**
 * Default validation rules.
 *
 * @param \Cake\Validation\Validator $validator
 * @return \Cake\Validation\Validator
 */
    public function validationDefault(Validator $validator) {
        $validator
            ->add('id', 'valid', ['rule' => 'numeric'])
            ->allowEmpty('id', 'create')
            ->validatePresence('title', 'create')
            ->notEmpty('title')
            ->allowEmpty('content')
            ->validatePresence('slug', 'create')
            ->notEmpty('slug')
            ->add('active', 'valid', ['rule' => 'boolean'])
            ->validatePresence('active', 'create')
            ->notEmpty('active')
            ->allowEmpty('intro')
            ->allowEmpty('thumbnail')
            ->allowEmpty('meta_title')
            ->allowEmpty('meta_keywords')
            ->allowEmpty('meta_description')
            ->add('system', 'valid', ['rule' => 'boolean'])
            ->allowEmpty('system')
            ->add('cms_language_id', 'valid', ['rule' => 'numeric'])
            ->allowEmpty('cms_language_id');

        return $validator;
    }

    public function findActive(Query $query, array $options) {
        $query->where([
            'CmsPages.active' => true
        ]);
        return $query;
    }
```
